type Tokens = { accessToken: string; refreshToken: string; expiresIn: number; role: string };
type Patient = { id: string; identityId: string; fullName: string; dob?: string; phone?: string; medicalHistory?: string; allergies?: string };
type Doctor = { id: string; identityId: string; fullName: string; specialtyCode: string; experienceYears: number; certificateNo?: string; avatarUrl?: string; bio?: string };
type WorkSchedule = { id: string; weekday: number; startTime: string; endTime: string; slotMinutes: number };
type LeavePeriod = { id: string; startAt: string; endAt: string; reason?: string };
type Appointment = { id: string; patientId: string; doctorId?: string; doctorIdentityId?: string; startAt: string; endAt: string; status: string; reason?: string; followUpReason?: string; followUpNotBefore?: string; holdExpiresAt?: string; createdAt: string };
type MedicalRecord = { id: string; appointmentId: string; patientId: string; finalDiagnosis: string; clinicalNotes?: string; treatmentPlan?: string; severity: string; followUpAt?: string; signedAt: string };
type PrescriptionItem = { drugName: string; dosage?: string; frequency?: string; duration?: string; instructions?: string };
type Prescription = { id: string; recordId: string; patientId: string; instructions?: string; signedAt: string; items: PrescriptionItem[] };
type Recommendation = { doctorId: string; doctorIdentityId: string; doctorName: string; specialtyCode: string; startAt: string; endAt: string; score: number; reasons: string[] };
type AvailabilitySlot = { doctorId: string; doctorIdentityId: string; doctorName: string; specialtyCode: string; startAt: string; endAt: string; status: "AVAILABLE" | "BOOKED" | "ON_LEAVE" | "HELD_BY_YOU" | "HELD_BY_OTHER"; holdId?: string; holdExpiresAt?: string };
type PatientNotification = { id: string; appointmentId?: string; notificationType: string; title: string; body: string; createdAt: string; readAt?: string };
type ClinicClosure = { id: string; closureDate: string; reason: string };
type ReminderAction = { id: string; appointmentId: string; actionType: "CALLED" | "RESENT" | "UNREACHABLE"; createdAt: string };
type ReminderItem = { appointment: Appointment; latestAction?: ReminderAction };
type RecommendationResult = { items: Recommendation[]; algorithmVersion: string; timezone: string };
type ClinicReview = { id: string; appointmentId: string; displayName: string; rating: number; comment: string; status: "PENDING" | "APPROVED" | "HIDDEN"; createdAt: string };
const API = "/api/v1";
async function request<T>(path: string, token?: string, init?: RequestInit): Promise<T> {
    const isForm = init?.body instanceof FormData;
    const response = await fetch(path.startsWith("/ai/") ? path : API + path, { ...init, headers: { ...(!isForm ? { "Content-Type": "application/json" } : {}), ...(token ? { Authorization: `Bearer ${token}` } : {}), ...init?.headers } });
    if (!response.ok) { const body = await response.json().catch(() => ({ detail: "Không thể kết nối dịch vụ." })); throw new Error(body.detail || `HTTP ${response.status}`) }
    if (response.status === 204) return undefined as T; return response.json();
}
function App() {
    const [session, setSession] = useState<Tokens | null>(() => { try { return JSON.parse(sessionStorage.getItem("dermai-session") || "null") } catch { return null } });
    const [authOpen, setAuthOpen] = useState(false); const [forgotOpen, setForgotOpen] = useState(false);
    if (!session) return forgotOpen ? <ForgotPassword close={() => setForgotOpen(false)} /> : authOpen ? <><button className="auth-home" onClick={() => setAuthOpen(false)}><X /> Về trang chủ</button><button className="auth-forgot" onClick={() => setForgotOpen(true)}>Quên mật khẩu?</button><Login onLogin={x => { sessionStorage.setItem("dermai-session", JSON.stringify(x)); setSession(x) }} /></> : <Home openAuth={() => setAuthOpen(true)} />;
    return <><Dashboard session={session} logout={() => { sessionStorage.removeItem("dermai-session"); setSession(null) }} />{session.role === "PATIENT" && <PatientNotifications session={session} />}{["PATIENT", "RECEPTIONIST"].includes(session.role) && <SupportChat session={session} />}</>;
}
